mapper.select:
SELECT r.* FROM payment_refund r
JOIN payment_intent i ON i.id = r.intent_id AND i.deleted = FALSE
WHERE r.deleted = FALSE

AND r.transaction_id = #{query.transactionId}
AND r.intent_id = #{query.intentId}
AND r.provider = #{query.provider}
AND r.status = #{query.status}
AND r.source_type = #{query.sourceType}
AND r.source_id = #{query.sourceId}

    AND (r.refund_no ILIKE CONCAT('%', #{query.keyword}, '%')
     OR r.provider_refund_no ILIKE CONCAT('%', #{query.keyword}, '%'))

ORDER BY r.created_at DESC, r.id DESC
